class Solution:
    def hasPathSum(self, root, targetSum):
        sums=[]
        def dfs(node,total):
            if not node: return
            total += node.val
            if not node.left and not node.right: sums.append(total)
            dfs(node.left,total); dfs(node.right,total)
        dfs(root,0)
        return targetSum in sums

